sp_widget.client_script:
api.controller = function($scope) {

    var c = this;


    /* =========================================================
       FILTERS
    ========================================================= */

    c.searchText = '';

    c.selectedBranch = '';

    c.selectedYear = '';

    c.selectedStatus = '';


    c.branches = [];

    c.years = [];


    /* =========================================================
       PAGINATION
    ========================================================= */

    c.currentPage = 1;

    c.pageSize = 8;

    c.totalPages = 1;

    c.filteredStudents = [];

    c.paginatedStudents = [];


    /* =========================================================
       MODAL
    ========================================================= */

    c.selectedStudent = null;

    c.studentInterviews = [];

    c.interviewApplicable = false;

    c.interviewsLoading = false;


    /* =========================================================
       BUILD FILTERS
    ========================================================= */

    c.buildFilterOptions = function() {

        var branchMap = {};

        var yearMap = {};

        var students =
            c.data.students || [];


        for (
            var i = 0;
            i < students.length;
            i++
        ) {

            var student =
                students[i];


            if (student.branch) {

                branchMap[
                    student.branch
                ] = true;

            }


            if (student.year) {

                yearMap[
                    student.year
                ] = true;

            }

        }


        c.branches =
            Object.keys(
                branchMap
            ).sort();


        c.years =
            Object.keys(
                yearMap
            ).sort();

    };


    /* =========================================================
       FILTER
    ========================================================= */

    c.applyFilters = function() {

        var students =
            c.data.students || [];


        var search =
            String(
                c.searchText || ''
            )
            .toLowerCase()
            .trim();


        c.filteredStudents =
            students.filter(
                function(student) {

                    if (search) {

                        var searchable =
                            [
                                student.name,
                                student.student_id,
                                student.email,
                                student.branch,
                                student.year,
                                student.cgpa,
                                student.placement_status
                            ]
                            .join(' ')
                            .toLowerCase();


                        if (
                            searchable.indexOf(
                                search
                            ) === -1
                        ) {

                            return false;

                        }

                    }


                    if (
                        c.selectedBranch &&
                        student.branch !==
                        c.selectedBranch
                    ) {

                        return false;

                    }


                    if (
                        c.selectedYear &&
                        student.year !==
                        c.selectedYear
                    ) {

                        return false;

                    }


                    if (
                        c.selectedStatus &&
                        student.placement_status !==
                        c.selectedStatus
                    ) {

                        return false;

                    }


                    return true;

                }
            );


        c.currentPage = 1;

        c.updatePagination();

    };


    /* =========================================================
       PAGINATION
    ========================================================= */

    c.updatePagination = function() {

        var total =
            c.filteredStudents.length;


        c.totalPages =
            Math.max(
                1,
                Math.ceil(
                    total /
                    c.pageSize
                )
            );


        var start =
            (
                c.currentPage - 1
            ) *
            c.pageSize;


        c.paginatedStudents =
            c.filteredStudents.slice(
                start,
                start + c.pageSize
            );

    };


    c.goFirst = function() {

        c.currentPage = 1;

        c.updatePagination();

    };


    c.previousPage = function() {

        if (
            c.currentPage > 1
        ) {

            c.currentPage--;

            c.updatePagination();

        }

    };


    c.nextPage = function() {

        if (
            c.currentPage <
            c.totalPages
        ) {

            c.currentPage++;

            c.updatePagination();

        }

    };


    c.goLast = function() {

        c.currentPage =
            c.totalPages;

        c.updatePagination();

    };


    /* =========================================================
       CLEAR SEARCH
    ========================================================= */

    c.clearSearch = function() {

        c.searchText = '';

        c.applyFilters();

    };


    /* =========================================================
       VIEW STUDENT
    ========================================================= */

    c.viewStudent = function(
        student
    ) {

        if (!student) {
            return;
        }


        if (!student.sys_id) {

            alert(
                'Student record ID is missing.'
            );

            return;

        }


        c.selectedStudent =
            student;


        c.studentInterviews = [];

        c.interviewApplicable =
            false;

        c.interviewsLoading =
            true;


        /*
         * Send Student sys_id.
         */

        c.server.get({

            action:
                'get_student_interviews',

            student_id:
                student.sys_id

        }).then(

            function(response) {

                var data =
                    response.data || {};


                c.studentInterviews =
                    data.studentInterviews ||
                    [];


                c.interviewApplicable =
                    data.interviewApplicable ===
                    true;


                c.interviewsLoading =
                    false;

            },

            function() {

                c.studentInterviews = [];

                c.interviewApplicable =
                    false;

                c.interviewsLoading =
                    false;


                alert(
                    'Unable to load interview details.'
                );

            }

        );

    };


    /* =========================================================
       CLOSE
    ========================================================= */

    c.closeStudent = function() {

        c.selectedStudent =
            null;

        c.studentInterviews =
            [];

        c.interviewApplicable =
            false;

        c.interviewsLoading =
            false;

    };


    /* =========================================================
       TOTAL
    ========================================================= */

    c.getInterviewCountDisplay =
        function() {

            if (
                !c.interviewApplicable
            ) {

                return '—';

            }


            return c.studentInterviews.length;

        };


    /* =========================================================
       PASSED
    ========================================================= */

    c.getPassedCountDisplay =
        function() {

            if (
                !c.interviewApplicable
            ) {

                return '—';

            }


            var count = 0;


            for (
                var i = 0;
                i < c.studentInterviews.length;
                i++
            ) {

                var result =
                    String(
                        c.studentInterviews[i]
                            .result || ''
                    )
                    .toLowerCase()
                    .trim();


                if (
                    result === 'pass' ||
                    result === 'passed' ||
                    result === 'selected'
                ) {

                    count++;

                }

            }


            return count;

        };


    /* =========================================================
       PENDING
    ========================================================= */

    c.getPendingCountDisplay =
        function() {

            if (
                !c.interviewApplicable
            ) {

                return '—';

            }


            var count = 0;


            for (
                var i = 0;
                i < c.studentInterviews.length;
                i++
            ) {

                var result =
                    String(
                        c.studentInterviews[i]
                            .result || ''
                    )
                    .toLowerCase()
                    .trim();


                if (
                    !result ||
                    result === 'pending'
                ) {

                    count++;

                }

            }


            return count;

        };


    /* =========================================================
       STATUS CLASS
    ========================================================= */

    c.getStatusClass = function(
        status
    ) {

        var value =
            String(
                status || ''
            )
            .toLowerCase()
            .replace(
                /[_-]/g,
                ' '
            )
            .trim();


        if (
            value.indexOf(
                'complete'
            ) !== -1
        ) {

            return 'nx-status-completed';

        }


        if (
            value.indexOf(
                'progress'
            ) !== -1
        ) {

            return 'nx-status-progress';

        }


        if (
            value.indexOf(
                'cancel'
            ) !== -1
        ) {

            return 'nx-status-cancelled';

        }


        return 'nx-status-scheduled';

    };


    /* =========================================================
       RESULT CLASS
    ========================================================= */

    c.getResultClass = function(
        result
    ) {

        var value =
            String(
                result || ''
            )
            .toLowerCase()
            .trim();


        if (
            value === 'pass' ||
            value === 'passed' ||
            value === 'selected'
        ) {

            return 'nx-result-pass';

        }


        if (
            value === 'fail' ||
            value === 'failed' ||
            value === 'rejected'
        ) {

            return 'nx-result-fail';

        }


        return 'nx-result-pending';

    };


    /* =========================================================
       EXPORT
    ========================================================= */

    c.exportExcel = function() {

        var students =
            c.filteredStudents || [];


        if (
            students.length === 0
        ) {

            alert(
                'There are no students to export.'
            );

            return;

        }


        var rows = [];


        rows.push([
            'Student',
            'Email',
            'Student ID',
            'Branch',
            'Year',
            'CGPA',
            'Backlogs',
            'Placement Status'
        ]);


        for (
            var i = 0;
            i < students.length;
            i++
        ) {

            var s =
                students[i];


            rows.push([

                csvSafe(s.name),

                csvSafe(s.email),

                csvSafe(s.student_id),

                csvSafe(s.branch),

                csvSafe(s.year),

                csvSafe(s.cgpa),

                csvSafe(s.backlogs),

                csvSafe(
                    s.placement_status
                )

            ]);

        }


        var csv =
            rows
                .map(
                    function(row) {
                        return row.join(',');
                    }
                )
                .join('\r\n');


        var blob =
            new Blob(
                [
                    '\uFEFF' + csv
                ],
                {
                    type:
                        'text/csv;charset=utf-8;'
                }
            );


        var url =
            window.URL.createObjectURL(
                blob
            );


        var link =
            document.createElement(
                'a'
            );


        link.href = url;

        link.download =
            'Nexora_Student_Directory.csv';


        document.body.appendChild(
            link
        );

        link.click();

        document.body.removeChild(
            link
        );


        window.URL.revokeObjectURL(
            url
        );

    };


    /* =========================================================
       CSV SAFE
    ========================================================= */

    function csvSafe(
        value
    ) {

        if (
            value === null ||
            value === undefined
        ) {

            return '""';

        }


        return '"' +
            String(value)
                .replace(
                    /"/g,
                    '""'
                ) +
            '"';

    }


    /* =========================================================
       INITIALIZE
    ========================================================= */

    c.buildFilterOptions();

    c.applyFilters();


    /* =========================================================
       CLEANUP
    ========================================================= */

    $scope.$on(
        '$destroy',
        function() {

            c.selectedStudent =
                null;

            c.studentInterviews =
                [];

        }
    );

};

sp_widget.css:
/* =========================================================
   NEXORA STUDENT DIRECTORY
========================================================= */

.nx-student-directory,
.nx-student-directory * {
    box-sizing: border-box;
}


.nx-student-directory {

    width:  77vw!important;

    min-height: 100vh;

    padding: 70px !important;

    background:
        linear-gradient(
            180deg,
            #ffffff,
            #ffffff
        ) !important;

    color: #243f52;

    font-family:
        "Inter",
        "Segoe UI",
        Arial,
        sans-serif;

}


/* =========================================================
   HERO
========================================================= */

.nx-directory-hero {

    position: relative;

    min-height: 190px;

    padding: 34px 38px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    overflow: hidden;

    border-radius: 22px;

    background:
        linear-gradient(
            125deg,
            #102f47,
            #174766 48%,
            #1f607f
        );

    box-shadow:
        0 18px 45px
        rgba(24,57,78,.16);

    color: #fff;

}


.nx-hero-content {

    position: relative;

    z-index: 5;

}


.nx-hero-kicker {

    margin-bottom: 9px;

    color: #ff7869;

    font-size: 10px;

    font-weight: 900;

    letter-spacing: 1.7px;

}


.nx-directory-hero h1 {

    margin: 0;

    color: #fff !important;

    font-size: 34px;

    font-weight: 800;

}


.nx-directory-hero p {

    max-width: 600px;

    margin: 11px 0 0;

    color: #c9dbe6 !important;

    font-size: 13px;

    line-height: 1.7;

}


.nx-hero-role {

    position: relative;

    z-index: 5;

    padding: 11px 15px;

    display: flex;

    align-items: center;

    gap: 8px;

    border:
        1px solid
        rgba(255,255,255,.14);

    border-radius: 12px;

    background:
        rgba(255,255,255,.08);

    color: #eaf4f8;

    font-size: 10px;

    font-weight: 800;

}


.nx-hero-decoration {

    position: absolute;

    border:
        1px solid
        rgba(255,255,255,.09);

    border-radius: 50%;

}


.nx-decoration-one {

    width: 320px;

    height: 320px;

    right: -100px;

    top: -150px;

}


.nx-decoration-two {

    width: 190px;

    height: 190px;

    right: 150px;

    bottom: -145px;

}


/* =========================================================
   STATS
========================================================= */

.nx-stat-grid {

    display: grid;

    grid-template-columns:
        repeat(3,1fr);

    gap: 18px;

    margin: 22px 0;

}


.nx-stat-card {

    min-height: 118px;

    padding: 22px;

    display: flex;

    align-items: center;

    gap: 17px;

    background: #fff;

    border:
        1px solid #e2e9ee;

    border-radius: 17px;

    box-shadow:
        0 8px 25px
        rgba(25,55,75,.055);

}


.nx-stat-icon {

    width: 53px;

    height: 53px;

    min-width: 53px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 15px;

    font-size: 20px;

}


.nx-blue {

    background: #edf5fb;

    color: #286184;

}


.nx-green {

    background: #eaf8f0;

    color: #2b865d;

}


.nx-orange {

    background: #fff3e8;

    color: #bd7236;

}


.nx-stat-number {

    color: #1c3d54;

    font-size: 27px;

    font-weight: 850;

}


.nx-stat-label {

    margin-top: 7px;

    color: #7e8d98;

    font-size: 11px;

}


/* =========================================================
   FILTER
========================================================= */

.nx-filter-bar {

    display: grid;

    grid-template-columns:
        2fr 1fr 1fr 1fr 120px;

    gap: 11px;

    padding: 14px;

    margin-bottom: 20px;

    background: #fff;

    border:
        1px solid #e0e7ec;

    border-radius: 15px;

}


.nx-search-box {

    position: relative;

}


.nx-search-box i {

    position: absolute;

    left: 16px;

    top: 50%;

    transform:
        translateY(-50%);

    color: #82929d;

}


.nx-search-box input {

    width: 100% !important;

    height: 47px !important;

    padding:
        0 40px 0 42px !important;

    border:
        1px solid #dbe4e9 !important;

    border-radius: 10px !important;

    background: #fff !important;

    color: #334f61 !important;

}


.nx-filter-select {

    height: 47px !important;

    padding: 0 12px !important;

    border:
        1px solid #dbe4e9 !important;

    border-radius: 10px !important;

    background: #fff !important;

    color: #536c7b !important;

}


.nx-export-btn {

    height: 47px;

    border: none;

    border-radius: 10px;

    background:
        linear-gradient(
            135deg,
            #1c5675,
            #267596
        );

    color: #fff;

    font-size: 10px;

    font-weight: 800;

    cursor: pointer;

}


/* =========================================================
   STUDENT PANEL
========================================================= */

.nx-students-panel {

    overflow: hidden;

    background: #fff;

    border:
        1px solid #dfe7ec;

    border-radius: 18px;

    box-shadow:
        0 9px 28px
        rgba(25,55,75,.055);

}


.nx-panel-header {

    min-height: 91px;

    padding: 22px 26px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    border-bottom:
        1px solid #edf1f4;

}


.nx-panel-kicker {

    color: #ff705f;

    font-size: 8px;

    font-weight: 900;

    letter-spacing: 1.3px;

}


.nx-panel-header h2 {

    margin: 4px 0 0;

    color: #213f54;

    font-size: 20px;

    font-weight: 800;

}


.nx-panel-header p {

    margin: 5px 0 0;

    color: #8a98a2;

    font-size: 10px;

}


.nx-panel-indicator {

    padding: 8px 12px;

    border-radius: 20px;

    background: #f1f7f4;

    color: #4c7d66;

    font-size: 9px;

    font-weight: 800;

}


.nx-panel-indicator span {

    display: inline-block;

    width: 7px;

    height: 7px;

    margin-right: 6px;

    border-radius: 50%;

    background: #38a56f;

}


/* =========================================================
   STUDENT TABLE
========================================================= */

.nx-table-scroll {

    width: 100%;

    overflow-x: auto;

}


.nx-student-table {

    width: 100%;

    min-width: 1000px;

    border-collapse: collapse;

}


.nx-student-table thead {

    background: #f7f9fb;

}


.nx-student-table th {

    height: 48px;

    padding: 0 15px;

    text-align: left;

    color: #758590;

    font-size: 8px;

    font-weight: 900;

    letter-spacing: .65px;

}


.nx-student-table td {

    height: 68px;

    padding: 8px 15px;

    color: #4c6473;

    font-size: 10px;

    border-bottom:
        1px solid #edf1f3;

}


.nx-student-name {

    display: flex;

    align-items: center;

    gap: 10px;

}


.nx-avatar {

    width: 39px;

    height: 39px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 11px;

    background: #e7f1f6;

    color: #2c6686;

    font-weight: 850;

}


.nx-student-details {

    display: flex;

    flex-direction: column;

}


.nx-student-details strong {

    color: #294559;

    font-size: 10px;

}


.nx-student-details span {

    margin-top: 4px;

    color: #929fa8;

    font-size: 8px;

}


.nx-cgpa {

    color: #26475c;

}


.nx-backlog {

    min-width: 28px;

    height: 28px;

    display: inline-flex;

    align-items: center;

    justify-content: center;

    border-radius: 50%;

    background: #eaf7ef;

    color: #2c865d;

}


.nx-backlog-danger {

    background: #fff0f0;

    color: #cf6060;

}


.nx-placement-status {

    display: inline-flex;

    align-items: center;

    gap: 6px;

    padding: 7px 10px;

    border-radius: 20px;

    font-size: 8px;

    font-weight: 850;

}


.nx-placed {

    background: #e9f7ef;

    color: #27855b;

}


.nx-not-placed {

    background: #fff2e8;

    color: #c37539;

}


.nx-view-button {

    height: 34px;

    min-width: 70px;

    border:
        1px solid #d2e0e7;

    border-radius: 8px;

    background: #fff;

    color: #2e617c;

    font-size: 9px;

    font-weight: 800;

    cursor: pointer;

}


.nx-view-button:hover {

    background: #edf6fa;

}


/* =========================================================
   PAGINATION
========================================================= */

.nx-pagination {

    min-height: 65px;

    display: flex;

    align-items: center;

    justify-content: center;

    gap: 7px;

}


.nx-pagination button {

    height: 34px;

    padding: 0 12px;

    border:
        1px solid #dce4e9;

    border-radius: 8px;

    background: #fff;

    color: #607583;

}


.nx-pagination button:disabled {

    opacity: .4;

}


/* =========================================================
   MODAL
========================================================= */

.nx-modal-overlay {

    position: fixed !important;

    inset: 0 !important;

    z-index: 99999 !important;

    padding: 25px;

    display: flex;

    align-items: center;

    justify-content: center;

    background:
        rgba(11,28,41,.70);

    backdrop-filter: blur(5px);

}


.nx-interview-modal {

    width: 97%;

    max-width: 1400px;

    max-height: 92vh;

    display: flex;

    flex-direction: column;

    overflow: hidden;

    background: #fff;

    border-radius: 20px;

    box-shadow:
        0 30px 90px
        rgba(0,0,0,.28);

}


/* =========================================================
   MODAL HEADER
========================================================= */

.nx-modal-header {

    min-height: 98px;

    padding: 20px 27px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    border-bottom:
        1px solid #e8edf0;

}


.nx-modal-kicker {

    color: #ff6e5e;

    font-size: 8px;

    font-weight: 900;

    letter-spacing: 1.4px;

}


.nx-modal-header h2 {

    margin: 5px 0 0;

    color: #203e53;

    font-size: 21px;

    font-weight: 850;

}


.nx-modal-header p {

    margin: 5px 0 0;

    color: #87959f;

    font-size: 9px;

}


.nx-modal-actions {

    display: flex;

    align-items: center;

    gap: 12px;

}


.nx-modal-status {

    padding: 7px 11px;

    border-radius: 20px;

    font-size: 8px;

    font-weight: 850;

}


.nx-modal-status-placed {

    background: #e9f7ef;

    color: #28865b;

}


.nx-modal-status-pending {

    background: #fff1e7;

    color: #bd7338;

}


.nx-modal-close {

    width: 37px;

    height: 37px;

    border: none;

    border-radius: 50%;

    background: #f0f3f5;

    color: #71828e;

}


/* =========================================================
   MODAL CONTENT
========================================================= */

.nx-interview-content {

    padding: 21px;

    overflow: auto;

}


/* =========================================================
   NOT APPLICABLE
========================================================= */

.nx-not-applicable {

    margin-bottom: 17px;

    padding: 15px 17px;

    display: flex;

    align-items: center;

    gap: 13px;

    border:
        1px solid #f1dfc9;

    border-radius: 12px;

    background: #fffaf3;

}


.nx-na-icon {

    width: 38px;

    height: 38px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 10px;

    background: #fff0da;

    color: #bd7b34;

}


.nx-not-applicable strong {

    display: block;

    color: #76512e;

    font-size: 10px;

}


.nx-not-applicable span {

    display: block;

    margin-top: 4px;

    color: #9a8064;

    font-size: 9px;

}


/* =========================================================
   SUMMARY
========================================================= */

.nx-interview-summary {

    display: grid;

    grid-template-columns:
        repeat(3,1fr);

    gap: 12px;

    margin-bottom: 17px;

}


.nx-summary-card {

    min-height: 65px;

    padding: 12px 15px;

    display: flex;

    align-items: center;

    gap: 11px;

    border:
        1px solid #e2e9ed;

    border-radius: 12px;

    background: #fafcfd;

}


.nx-summary-card i {

    width: 36px;

    height: 36px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 10px;

    background: #edf4f8;

    color: #2b6684;

}


.nx-summary-card strong {

    display: block;

    color: #29495d;

    font-size: 17px;

}


.nx-summary-card span {

    display: block;

    margin-top: 3px;

    color: #8c99a2;

    font-size: 7px;

    font-weight: 850;

}


/* =========================================================
   INTERVIEW TABLE
========================================================= */

.nx-interview-scroll {

    width: 100%;

    overflow-x: auto;

    border:
        1px solid #e1e8ec;

    border-radius: 12px;

}


.nx-interview-table {

    width: 100%;

    min-width: 1250px;

    border-collapse: collapse;

}


.nx-interview-table thead {

    background: #f7f9fb;

}


.nx-interview-table th {

    height: 46px;

    padding: 0 12px;

    text-align: left;

    color: #788893;

    font-size: 7px;

    font-weight: 900;

    letter-spacing: .6px;

    white-space: nowrap;

}


.nx-interview-table td {

    height: 62px;

    padding: 9px 12px;

    color: #4c6473;

    font-size: 9px;

    border-bottom:
        1px solid #edf1f3;

    white-space: nowrap;

}


.nx-number {

    width: 24px;

    height: 24px;

    display: inline-flex;

    align-items: center;

    justify-content: center;

    border-radius: 50%;

    background: #edf3f6;

    color: #607582;

}


.nx-drive-name {

    color: #315e76;

    font-weight: 750;

}


.nx-company {

    display: flex;

    align-items: center;

    gap: 8px;

}


.nx-company-avatar {

    width: 31px;

    height: 31px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 8px;

    background: #edf4f8;

    color: #28627f;

    font-weight: 900;

}


.nx-round {

    padding: 6px 9px;

    border-radius: 20px;

    background: #eef4f8;

    color: #35647c;

    font-size: 8px;

    font-weight: 800;

}


.nx-interviewer {

    display: inline-flex;

    align-items: center;

    gap: 6px;

    color: #4c6675;

}


.nx-interviewer i {

    color: #7d929e;

}


.nx-interview-status,
.nx-interview-result {

    display: inline-flex;

    padding: 6px 9px;

    border-radius: 20px;

    font-size: 7px;

    font-weight: 850;

}


.nx-status-completed {

    background: #e8f7ee;

    color: #28845a;

}


.nx-status-progress {

    background: #fff4e7;

    color: #b57431;

}


.nx-status-cancelled {

    background: #fff0f0;

    color: #c85d5d;

}


.nx-status-scheduled {

    background: #edf5fb;

    color: #356886;

}


.nx-result-pass {

    background: #e8f7ee;

    color: #27845a;

}


.nx-result-fail {

    background: #fff0f0;

    color: #c65c5c;

}


.nx-result-pending {

    background: #fff5e8;

    color: #b87935;

}


.nx-feedback {

    display: block;

    max-width: 190px;

    overflow: hidden;

    text-overflow: ellipsis;

    color: #778994;

}


/* =========================================================
   NULL ROW
========================================================= */

.nx-null-row td {

    height: 100px;

    text-align: center;

    color: #aab4ba !important;

    font-size: 12px !important;

}


/* =========================================================
   NO RECORD
========================================================= */

.nx-no-record-content {

    min-height: 150px;

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;

    text-align: center;

}


.nx-no-record-content i {

    margin-bottom: 9px;

    color: #899ba6;

    font-size: 22px;

}


.nx-no-record-content strong {

    color: #536b79;

    font-size: 11px;

}


.nx-no-record-content span {

    margin-top: 5px;

    color: #9aa6ad;

    font-size: 9px;

}


/* =========================================================
   LOADING
========================================================= */

.nx-interview-loading {

    min-height: 320px;

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;

    gap: 8px;

    color: #7d8f9b;

}


.nx-interview-loading i {

    color: #28627f;

    font-size: 24px;

}


/* =========================================================
   FOOTER
========================================================= */

.nx-modal-footer {

    min-height: 66px;

    padding: 13px 23px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    border-top:
        1px solid #edf1f3;

}


.nx-modal-footer-info {

    color: #8998a2;

    font-size: 8px;

    font-weight: 700;

}


.nx-modal-footer button {

    height: 36px;

    padding: 0 20px;

    border: none;

    border-radius: 8px;

    background: #205a79;

    color: #fff;

    font-size: 9px;

    font-weight: 800;

}


/* =========================================================
   ACCESS DENIED
========================================================= */

.nx-access-denied {

    min-height: 500px;

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;

    text-align: center;

}


.nx-access-icon {

    width: 61px;

    height: 61px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 16px;

    background: #fff0ed;

    color: #df6758;

    font-size: 23px;

}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width:1150px) {

    .nx-filter-bar {

        grid-template-columns:
            1fr 1fr;

    }

    .nx-search-box {

        grid-column: 1 / -1;

    }

}


@media (max-width:850px) {

    .nx-student-directory {

        padding: 20px 15px 35px !important;

    }

    .nx-stat-grid {

        grid-template-columns: 1fr;

    }

    .nx-directory-hero {

        padding: 27px;

    }

    .nx-hero-role {

        display: none;

    }

    .nx-interview-summary {

        grid-template-columns: 1fr;

    }

}

sp_widget.script:
(function() {

    /* =========================================================
       NEXORA STUDENT DIRECTORY
       SERVER SCRIPT
    ========================================================= */

    data.authorized = false;

    data.role = '';

    data.students = [];

    data.totalStudents = 0;

    data.placedStudents = 0;

    data.availableStudents = 0;

    data.studentInterviews = [];

    data.interviewApplicable = false;


    /* =========================================================
       ROLE CHECK
    ========================================================= */

    var isAdmin =
        gs.hasRole(
            'x_snc_college_pl_0.placement_admin'
        );

    var isOfficer =
        gs.hasRole(
            'x_snc_college_pl_0.placement_officer'
        );


    if (!isAdmin && !isOfficer) {
        return;
    }


    data.authorized = true;


    if (isAdmin) {
        data.role = 'Placement Admin';
    } else {
        data.role = 'Placement Officer';
    }


    /* =========================================================
       VIEW STUDENT REQUEST
    ========================================================= */

    if (
        input &&
        input.action ===
        'get_student_interviews'
    ) {

        var studentId =
            String(
                input.student_id || ''
            ).trim();


        if (!studentId) {
            return;
        }


        var studentCheck =
            new GlideRecord(
                'x_snc_college_pl_0_student'
            );


        if (
            !studentCheck.isValid() ||
            !studentCheck.get(studentId)
        ) {

            return;

        }


        /*
         * Check placement.
         */

        if (
            !isStudentPlaced(
                studentId
            )
        ) {

            data.interviewApplicable =
                false;

            data.studentInterviews = [];

            return;

        }


        /*
         * Student is placed.
         */

        data.interviewApplicable =
            true;

        data.studentInterviews = [];


        loadStudentInterviews(
            studentId
        );


        return;

    }


    /* =========================================================
       STUDENT TABLE
    ========================================================= */

    var studentGR =
        new GlideRecord(
            'x_snc_college_pl_0_student'
        );


    if (!studentGR.isValid()) {

        gs.error(
            'NEXORA: Student table invalid.'
        );

        return;

    }


    var nameField =
        findField(
            studentGR,
            [
                'name',
                'full_name',
                'student_name'
            ]
        );


    var studentIdField =
        findField(
            studentGR,
            [
                'student_id',
                'register_number',
                'registration_number',
                'roll_number'
            ]
        );


    var branchField =
        findField(
            studentGR,
            [
                'branch',
                'department',
                'branch_name'
            ]
        );


    var yearField =
        findField(
            studentGR,
            [
                'year',
                'academic_year',
                'year_of_study'
            ]
        );


    var cgpaField =
        findField(
            studentGR,
            [
                'cgpa',
                'gpa'
            ]
        );


    var backlogField =
        findField(
            studentGR,
            [
                'backlogs',
                'backlog_count',
                'no_of_backlogs'
            ]
        );


    var placementField =
        findField(
            studentGR,
            [
                'placement_status',
                'placementStatus'
            ]
        );


    var emailField =
        findField(
            studentGR,
            [
                'email'
            ]
        );


    /* =========================================================
       APPLICATION PLACEMENT MAP
    ========================================================= */

    var placementMap = {};


    var appGR =
        new GlideRecord(
            'x_snc_college_pl_0_application'
        );


    if (appGR.isValid()) {

        appGR.query();


        while (appGR.next()) {

            var appStudent =
                appGR.getValue(
                    'student'
                );


            if (!appStudent) {
                continue;
            }


            var appStatus =
                normalize(
                    appGR.getDisplayValue(
                        'status'
                    )
                );


            if (
                appStatus.indexOf(
                    'selected'
                ) !== -1 ||

                appStatus.indexOf(
                    'offered'
                ) !== -1 ||

                appStatus.indexOf(
                    'placed'
                ) !== -1
            ) {

                placementMap[
                    appStudent
                ] = true;

            }

        }

    }


    /* =========================================================
       LOAD STUDENTS
    ========================================================= */

    studentGR.orderBy('name');

    studentGR.query();


    while (studentGR.next()) {

        var student = {};

        student.sys_id =
            studentGR.getUniqueValue();


        /* NAME */

        var studentName = '';


        if (nameField) {

            studentName =
                studentGR.getDisplayValue(
                    nameField
                );

        }


        if (!studentName) {
            studentName = 'Student';
        }


        student.name =
            studentName;


        student.initial =
            getInitial(
                studentName
            );


        /* EMAIL */

        student.email =
            emailField
                ?
                studentGR.getValue(
                    emailField
                ) || ''
                :
                '';


        /* STUDENT ID */

        student.student_id =
            studentIdField
                ?
                studentGR.getDisplayValue(
                    studentIdField
                )
                :
                '';


        /* BRANCH */

        student.branch =
            branchField
                ?
                studentGR.getDisplayValue(
                    branchField
                )
                :
                '';


        /* YEAR */

        student.year =
            yearField
                ?
                studentGR.getDisplayValue(
                    yearField
                )
                :
                '';


        /* CGPA */

        student.cgpa =
            cgpaField
                ?
                studentGR.getValue(
                    cgpaField
                ) || ''
                :
                '';


        /* BACKLOGS */

        var backlog = 0;


        if (backlogField) {

            backlog =
                parseInt(
                    studentGR.getValue(
                        backlogField
                    ),
                    10
                );

        }


        if (isNaN(backlog)) {
            backlog = 0;
        }


        student.backlogs =
            backlog;


        /* PLACEMENT STATUS */

        var placementStatus = '';


        if (placementField) {

            placementStatus =
                studentGR.getDisplayValue(
                    placementField
                ) || '';

        }


        var normalizedPlacement =
            normalize(
                placementStatus
            );


        if (
            normalizedPlacement.indexOf(
                'placed'
            ) !== -1 ||

            normalizedPlacement.indexOf(
                'selected'
            ) !== -1
        ) {

            placementStatus =
                'Placed';

        }

        else if (
            placementMap[
                student.sys_id
            ]
        ) {

            placementStatus =
                'Placed';

        }

        else {

            placementStatus =
                'Not Placed';

        }


        student.placement_status =
            placementStatus;


        data.students.push(
            student
        );

    }


    /* =========================================================
       COUNTS
    ========================================================= */

    data.totalStudents =
        data.students.length;


    for (
        var x = 0;
        x < data.students.length;
        x++
    ) {

        if (
            data.students[x]
                .placement_status ===
            'Placed'
        ) {

            data.placedStudents++;

        }

    }


    data.availableStudents =
        data.totalStudents -
        data.placedStudents;


    /* =========================================================
       IS STUDENT PLACED?
    ========================================================= */

    function isStudentPlaced(
        studentId
    ) {

        /*
         * 1. Student placement_status
         */

        var student =
            new GlideRecord(
                'x_snc_college_pl_0_student'
            );


        if (
            student.get(
                studentId
            )
        ) {

            var placementField =
                findField(
                    student,
                    [
                        'placement_status',
                        'placementStatus'
                    ]
                );


            if (placementField) {

                var status =
                    normalize(
                        student.getDisplayValue(
                            placementField
                        )
                    );


                if (
                    status.indexOf(
                        'placed'
                    ) !== -1 ||

                    status.indexOf(
                        'selected'
                    ) !== -1
                ) {

                    return true;

                }

            }

        }


        /*
         * 2. Application status
         */

        var application =
            new GlideRecord(
                'x_snc_college_pl_0_application'
            );


        application.addQuery(
            'student',
            studentId
        );


        application.query();


        while (
            application.next()
        ) {

            var appStatus =
                normalize(
                    application.getDisplayValue(
                        'status'
                    )
                );


            if (
                appStatus.indexOf(
                    'selected'
                ) !== -1 ||

                appStatus.indexOf(
                    'offered'
                ) !== -1 ||

                appStatus.indexOf(
                    'placed'
                ) !== -1
            ) {

                return true;

            }

        }


        return false;

    }


    /* =========================================================
       LOAD INTERVIEWS
    ========================================================= */

    function loadStudentInterviews(
        studentId
    ) {

        var interviews =
            new GlideRecord(
                'x_snc_college_pl_0_interview'
            );


        if (!interviews.isValid()) {

            gs.error(
                'NEXORA: Interview table invalid.'
            );

            return;

        }


        /*
         * FIRST:
         * Direct Interview.student
         */

        if (
            interviews.isValidField(
                'student'
            )
        ) {

            interviews.addQuery(
                'student',
                studentId
            );

            interviews.orderByDesc(
                'interview_date'
            );

            interviews.query();


            while (
                interviews.next()
            ) {

                data.studentInterviews.push(
                    buildInterview(
                        interviews,
                        studentId
                    )
                );

            }


            if (
                data.studentInterviews.length > 0
            ) {

                return;

            }

        }


        /*
         * SECOND:
         * Interview.application
         *
         * Application.student
         */

        if (
            !interviews.isValidField(
                'application'
            )
        ) {

            return;

        }


        var applications = [];


        var application =
            new GlideRecord(
                'x_snc_college_pl_0_application'
            );


        application.addQuery(
            'student',
            studentId
        );


        application.query();


        while (
            application.next()
        ) {

            applications.push(
                application.getUniqueValue()
            );

        }


        if (
            applications.length === 0
        ) {

            return;

        }


        var interviewByApplication =
            new GlideRecord(
                'x_snc_college_pl_0_interview'
            );


        interviewByApplication.addQuery(
            'application',
            'IN',
            applications.join(',')
        );


        interviewByApplication.orderByDesc(
            'interview_date'
        );


        interviewByApplication.query();


        while (
            interviewByApplication.next()
        ) {

            data.studentInterviews.push(
                buildInterview(
                    interviewByApplication,
                    studentId
                )
            );

        }

    }


    /* =========================================================
       BUILD INTERVIEW
    ========================================================= */

    function buildInterview(
        interview,
        studentId
    ) {

        var result = {};


        result.sys_id =
            interview.getUniqueValue();


        result.studentId =
            studentId;


        /* =====================================================
           APPLICATION
        ===================================================== */

        var applicationId = '';


        if (
            interview.isValidField(
                'application'
            )
        ) {

            applicationId =
                interview.getValue(
                    'application'
                ) || '';

        }


        result.application =
            applicationId;


        /* =====================================================
           INTERVIEW DRIVE
        ===================================================== */

        var driveId = '';

        var driveName = '';


        if (
            interview.isValidField(
                'drive'
            )
        ) {

            driveId =
                interview.getValue(
                    'drive'
                ) || '';


            driveName =
                interview.getDisplayValue(
                    'drive'
                ) || '';

        }


        /*
         * Some of your screenshot records show
         * Interview Drive as empty.
         *
         * Therefore:
         *
         * Interview Drive
         *       ↓
         * if empty
         *       ↓
         * Application Drive
         */

        if (
            !driveId &&
            applicationId
        ) {

            var application =
                new GlideRecord(
                    'x_snc_college_pl_0_application'
                );


            if (
                application.get(
                    applicationId
                )
            ) {

                if (
                    application.isValidField(
                        'drive'
                    )
                ) {

                    driveId =
                        application.getValue(
                            'drive'
                        ) || '';


                    driveName =
                        application.getDisplayValue(
                            'drive'
                        ) || '';

                }

            }

        }


        result.drive =
            driveId;


        result.driveName =
            driveName;


        /* =====================================================
           COMPANY
        ===================================================== */

        var company = '';


        /*
         * 1. Interview.company
         */

        company =
            getFirstValidDisplay(
                interview,
                [
                    'company',
                    'company_name'
                ]
            );


        /*
         * 2. Placement Drive.company
         */

        if (
            !company &&
            driveId
        ) {

            var drive =
                new GlideRecord(
                    'x_snc_college_pl_0_placement_drive'
                );


            if (
                drive.get(
                    driveId
                )
            ) {

                company =
                    getFirstValidDisplay(
                        drive,
                        [
                            'company',
                            'company_name'
                        ]
                    );


                /*
                 * Drive name fallback
                 */

                if (!driveName) {

                    driveName =
                        getFirstValidDisplay(
                            drive,
                            [
                                'drive_name',
                                'name'
                            ]
                        );

                    result.driveName =
                        driveName;

                }

            }

        }


        result.company =
            company;


        result.companyInitial =
            getInitial(
                company
            );


        /* =====================================================
           ROUND NAME
        ===================================================== */

        result.roundName =
            getFirstValidDisplay(
                interview,
                [
                    'round_name',
                    'round',
                    'interview_round'
                ]
            );


        /* =====================================================
           INTERVIEW DATE
        ===================================================== */

        var rawInterviewDate = '';


        if (
            interview.isValidField(
                'interview_date'
            )
        ) {

            rawInterviewDate =
                interview.getValue(
                    'interview_date'
                ) || '';

        }


        var displayInterviewDate = '';


        if (
            interview.isValidField(
                'interview_date'
            )
        ) {

            displayInterviewDate =
                interview.getDisplayValue(
                    'interview_date'
                ) || '';

        }


        result.rawInterviewDate =
            rawInterviewDate;


        result.date =
            displayInterviewDate;


        /*
         * Extract time from Date/Time.
         */

        result.time =
            extractTime(
                rawInterviewDate,
                displayInterviewDate
            );


        /* =====================================================
           INTERVIEWER
        ===================================================== */

        result.interviewer =
            getFirstValidDisplay(
                interview,
                [
                    'interviewer',
                    'assigned_to',
                    'interviewer_user'
                ]
            );


        /* =====================================================
           STATUS
        ===================================================== */

        result.status =
            getFirstValidDisplay(
                interview,
                [
                    'status',
                    'state'
                ]
            );


        /* =====================================================
           RESULT
        ===================================================== */

        result.result =
            getFirstValidDisplay(
                interview,
                [
                    'result',
                    'interview_result'
                ]
            );


        /* =====================================================
           FEEDBACK
        ===================================================== */

        result.feedback =
            getFirstValidDisplay(
                interview,
                [
                    'feedback',
                    'interview_feedback'
                ]
            );


        return result;

    }


    /* =========================================================
       GET DISPLAY VALUE
    ========================================================= */

    function getFirstValidDisplay(
        gr,
        fields
    ) {

        for (
            var i = 0;
            i < fields.length;
            i++
        ) {

            var field =
                fields[i];


            if (
                !gr.isValidField(
                    field
                )
            ) {

                continue;

            }


            var value =
                gr.getDisplayValue(
                    field
                );


            if (
                value !== null &&
                value !== undefined &&
                String(value).trim() !== ''
            ) {

                return String(
                    value
                ).trim();

            }


            /*
             * Fallback to raw value.
             */

            value =
                gr.getValue(
                    field
                );


            if (
                value !== null &&
                value !== undefined &&
                String(value).trim() !== ''
            ) {

                return String(
                    value
                ).trim();

            }

        }


        return '';

    }


    /* =========================================================
       FIND FIELD
    ========================================================= */

    function findField(
        gr,
        fields
    ) {

        for (
            var i = 0;
            i < fields.length;
            i++
        ) {

            if (
                gr.isValidField(
                    fields[i]
                )
            ) {

                return fields[i];

            }

        }


        return '';

    }


    /* =========================================================
       NORMALIZE
    ========================================================= */

    function normalize(
        value
    ) {

        return String(
            value || ''
        )
        .toLowerCase()
        .replace(
            /[_-]/g,
            ' '
        )
        .replace(
            /\s+/g,
            ' '
        )
        .trim();

    }


    /* =========================================================
       INITIAL
    ========================================================= */

    function getInitial(
        value
    ) {

        if (!value) {
            return '—';
        }


        return String(
            value
        )
        .trim()
        .charAt(0)
        .toUpperCase();

    }


    /* =========================================================
       EXTRACT TIME
    ========================================================= */

    function extractTime(
        rawValue,
        displayValue
    ) {

        /*
         * Example:
         *
         * 2026-10-22 05:29:58
         *
         * returns:
         *
         * 05:29:58
         */

        if (rawValue) {

            var raw =
                String(
                    rawValue
                );


            var match =
                raw.match(
                    /(\d{2}:\d{2}:\d{2})/
                );


            if (match) {

                return match[1];

            }

        }


        /*
         * Fallback to display value.
         */

        if (displayValue) {

            var display =
                String(
                    displayValue
                );


            var displayMatch =
                display.match(
                    /(\d{1,2}:\d{2}(?::\d{2})?\s*(?:AM|PM)?)/i
                );


            if (displayMatch) {

                return displayMatch[1];

            }

        }


        return '';

    }


})();
